//! How many people bear a name, and which names are nicknames of which.
//!
//! SCOWL ranks nearly every proper name at one level, so on its own it cannot
//! tell `Owen` from `Kant`, nor `Sara` (a name) from `Sarha` (a slip). The
//! Census tables can: a given name and a surname are both a share of the
//! people who bear them, one scale for both. Generated by
//! `script/build-names.sh`; see it for sources and cutoffs.

use std::sync::OnceLock;

const NAMES: &str = include_str!("../data/names.txt");
const NICKNAMES: &str = include_str!("../data/nicknames.txt");

/// The share of US people bearing a name, per million.
#[derive(Debug, Clone, Copy, PartialEq, Default)]
pub struct Share {
    pub given: Option<f32>,
    pub surname: Option<f32>,
}

impl Share {
    /// The commoner reading: `Owen` counts as the given name it mostly is.
    pub fn people(&self) -> f32 {
        self.given.unwrap_or(0.0).max(self.surname.unwrap_or(0.0))
    }
}

type Table = Vec<(&'static str, Share)>;

fn names() -> &'static Table {
    static TABLE: OnceLock<Table> = OnceLock::new();
    TABLE.get_or_init(|| parse_names(NAMES))
}

fn parse_names(text: &'static str) -> Table {
    let field = |f: Option<&str>| f.and_then(|v| v.parse::<f32>().ok());
    text.lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
        .filter_map(|l| {
            let mut parts = l.split('\t');
            let name = parts.next()?;
            let share = Share {
                given: field(parts.next()),
                surname: field(parts.next()),
            };
            Some((name, share))
        })
        .collect()
}

/// Nickname pairs, sorted by nickname.
fn nickname_pairs() -> &'static Vec<(&'static str, &'static str)> {
    static PAIRS: OnceLock<Vec<(&'static str, &'static str)>> = OnceLock::new();
    PAIRS.get_or_init(|| {
        NICKNAMES
            .lines()
            .filter(|l| !l.starts_with('#') && !l.is_empty())
            .filter_map(|l| l.split_once('\t'))
            .collect()
    })
}

/// How many people bear `name` (lowercase), if the Census lists it.
pub fn share(name: &str) -> Option<Share> {
    let table = names();
    table
        .binary_search_by(|(n, _)| (*n).cmp(name))
        .ok()
        .map(|i| table[i].1)
}

/// The full names `nickname` is short for: `bob` → `robert`.
pub fn full_names(nickname: &str) -> Vec<&'static str> {
    let pairs = nickname_pairs();
    let start = pairs.partition_point(|(n, _)| *n < nickname);
    pairs[start..]
        .iter()
        .take_while(|(n, _)| *n == nickname)
        .map(|(_, full)| *full)
        .collect()
}

/// The nicknames of `full`: `robert` → `bob`, `bobby`, `rob`.
pub fn nicknames(full: &str) -> Vec<&'static str> {
    let mut out: Vec<&str> = nickname_pairs()
        .iter()
        .filter(|(_, f)| *f == full)
        .map(|(n, _)| *n)
        .collect();
    out.sort_unstable();
    out
}

/// Is `name` (lowercase) a name people bear: in the Census tables, or in the
/// nickname table? Spelling variants count — `Sara` is a name, not a slip
/// for `Sarah` — which is the point.
pub fn is_known(name: &str) -> bool {
    share(name).is_some() || !full_names(name).is_empty() || !nicknames(name).is_empty()
}

/// Could `a` and `b` (lowercase) name the same person? The same name, one a
/// nickname of the other (`bob`, `robert`), or nicknames of one full name
/// (`bill`, `will`).
pub fn same_name(a: &str, b: &str) -> bool {
    if a == b {
        return true;
    }
    let (fa, fb) = (full_names(a), full_names(b));
    fa.contains(&b) || fb.contains(&a) || fa.iter().any(|f| fb.contains(f))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_tables_are_sorted_for_binary_search() {
        assert!(names().windows(2).all(|w| w[0].0 < w[1].0));
        assert!(nickname_pairs().windows(2).all(|w| w[0] <= w[1]));
    }

    #[test]
    fn a_name_has_a_share_of_people_by_kind() {
        let owen = share("owen").unwrap();
        assert!(owen.given.is_some() && owen.surname.is_some());
        assert!(share("smith").unwrap().given.is_none());
        assert!(share("john").unwrap().people() > share("owen").unwrap().people());
        assert_eq!(share("zblorg"), None);
    }

    #[test]
    fn a_spelling_variant_is_a_name_and_a_slip_is_not() {
        assert!(is_known("sara") && is_known("sarah"));
        assert!(!is_known("sarha"));
    }

    #[test]
    fn nicknames_relate_both_ways_and_through_a_shared_full_name() {
        assert!(full_names("bob").contains(&"robert"));
        assert!(nicknames("robert").contains(&"bob"));
        assert!(same_name("bob", "robert") && same_name("robert", "bob"));
        assert!(same_name("bill", "will"));
        assert!(!same_name("bob", "sally"));
    }
}
